def step(g, R, C):
    out = []
    for y in range(R):
        row = ''
        for x in range(C):
            t = 0
            for dy in (-1, 0, 1):
                for dx in (-1, 0, 1):
                    a, b = y + dy, x + dx
                    if 0 <= a < R and 0 <= b < C and g[a][b] == '#':
                        t += 1
            row += '#' if (t == 3 or (t == 4 and g[y][x] == '#')) else '.'
        out.append(row)
    return out


def generate(seed):
    r = random.Random(seed)
    R = C = 6
    while True:
        d = r.choice([0.3, 0.35, 0.4, 0.45])
        p = [''.join('#' if r.random() < d else '.' for _ in range(C)) for _ in range(R)]
        t = step(p, R, C)
        if sum(row.count('#') for row in t) < 5:
            continue
        if step(t, R, C) == t:
            continue
        return '\n'.join(t)

