def solve(clue):
    T = clue.split('\n')
    R = len(T); C = len(T[0]); M = 1 << C
    tr = [sum(1 << x for x in range(C) if T[y][x] == '#') for y in range(R)]
    H = []
    for m in range(M):
        H.append([(m >> (x - 1) & 1 if x else 0) + (m >> x & 1) +
                  (m >> (x + 1) & 1 if x + 1 < C else 0) for x in range(C)])

    def nxt(a, b, cc):
        v = 0
        Ha, Hb, Hc = H[a], H[b], H[cc]
        for x in range(C):
            t = Ha[x] + Hb[x] + Hc[x]
            if t == 3 or (t == 4 and b >> x & 1):
                v |= 1 << x
        return v

    dp = {}
    for a in range(M):
        for b in range(M):
            if nxt(0, a, b) == tr[0]:
                dp[(a, b)] = [a]
    for y in range(1, R):
        nd = {}
        opts = [0] if y == R - 1 else range(M)
        for ab, path in dp.items():
            a, b = ab
            for cc in opts:
                if nxt(a, b, cc) == tr[y]:
                    k = (b, cc)
                    if k not in nd:
                        nd[k] = path + [b]
        dp = nd
        if not dp:
            return ''
    rows = next(iter(dp.values()))
    return '\n'.join(''.join('#' if m >> x & 1 else '.' for x in range(C)) for m in rows)

